CREATE OR REPLACE FUNCTION public.ensure_delivery_custody_snapshot_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.order_type='delivery'
     and new.status in ('delivered','completed')
     and new.driver_id is not null
     and new.driver_settled_at is null then
    if lower(coalesce(new.payment_method,''))='cash' then
      if coalesce(new.delivery_cash_custody_amount,0)<=0 then
        new.delivery_cash_custody_amount:=round(coalesce(new.total,0),2);
      end if;
      if new.delivery_payment_finalized_at is null then
        new.delivery_payment_finalized_at:=coalesce(new.delivered_at,now());
      end if;
    elsif coalesce(new.delivery_cash_custody_amount,0)<>0 then
      new.delivery_cash_custody_amount:=0;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.rc1_assert_delivery_required_fields_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_phone text;
begin
  if coalesce(new.order_type,'') <> 'delivery' then
    return new;
  end if;

  v_phone := regexp_replace(coalesce(new.customer_phone,''),'[^0-9]','','g');
  if left(v_phone,4)='0020' then
    v_phone := substr(v_phone,5);
  elsif left(v_phone,2)='20' and length(v_phone)>=12 then
    v_phone := substr(v_phone,3);
  elsif length(v_phone)=10 and left(v_phone,1)='1' then
    v_phone := '0'||v_phone;
  end if;

  if v_phone !~ '^01[0125][0-9]{8}$' then
    raise exception using errcode='22023', message='رقم موبايل الدليفري غير صحيح — اكتب رقم مصري 11 رقم';
  end if;
  if nullif(trim(coalesce(new.delivery_address,'')),'') is null then
    raise exception using errcode='22023', message='عنوان التوصيل مطلوب لأوردر الدليفري';
  end if;
  if new.delivery_zone_id is null then
    raise exception using errcode='22023', message='منطقة التوصيل مطلوبة لأوردر الدليفري';
  end if;
  if not exists(
    select 1
    from public.delivery_zones z
    where z.id=new.delivery_zone_id
      and z.branch_id=new.branch_id
      and z.active=true
  ) then
    raise exception using errcode='22023', message='منطقة التوصيل غير صحيحة أو لا تتبع نفس الفرع';
  end if;

  new.customer_phone := v_phone;
  new.delivery_address := trim(new.delivery_address);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.offline_v2_emit_order_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text;
  v_source text := case when coalesce(new.source,'')='website' then 'website' else 'cloud' end;
begin
  if tg_op='INSERT' then
    v_type := case when coalesce(new.source,'')='website' then 'website.order_created' else 'order.created' end;
  elsif new.status is distinct from old.status then
    v_type := 'order.status_changed';
  elsif new.payment_status is distinct from old.payment_status then
    v_type := 'order.payment_changed';
  elsif new.driver_id is distinct from old.driver_id then
    v_type := 'order.driver_changed';
  else
    v_type := 'order.updated';
  end if;

  insert into public.offline_v2_domain_events(branch_id,event_type,entity_type,entity_id,source,payload)
  values(new.branch_id,v_type,'order',new.id::text,v_source,to_jsonb(new));
  return new;
end;
$function$

