CREATE OR REPLACE FUNCTION public.is_branch_website_schedule_open(p_branch_id bigint, p_at timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_business_id uuid;
  s public.branch_website_settings%rowtype;
  today_hours public.branch_website_hours%rowtype;
  prev_hours public.branch_website_hours%rowtype;
  local_ts timestamp without time zone;
  local_dow integer;
  local_time time without time zone;
  prev_dow integer;
begin
  v_business_id:=public.mt1_require_request_business();
  perform public.mt1_require_public_branch(p_branch_id);
  select * into s
  from public.branch_website_settings
  where branch_id = p_branch_id
    and business_id=v_business_id;

  if not found or not coalesce(s.schedule_enabled, false) then
    return true;
  end if;

  begin
    local_ts := p_at at time zone coalesce(nullif(trim(s.schedule_timezone), ''), 'Africa/Cairo');
  exception when invalid_parameter_value then
    local_ts := p_at at time zone 'Africa/Cairo';
  end;

  local_dow := extract(dow from local_ts)::integer;
  local_time := local_ts::time;
  prev_dow := (local_dow + 6) % 7;

  select * into today_hours
  from public.branch_website_hours
  where branch_id = p_branch_id
    and business_id=v_business_id
    and day_of_week = local_dow;

  if found and coalesce(today_hours.enabled, false) then
    -- Equal open/close means 24 hours for that day.
    if today_hours.open_time = today_hours.close_time then
      return true;
    end if;

    if today_hours.open_time < today_hours.close_time then
      if local_time >= today_hours.open_time
         and local_time < today_hours.close_time then
        return true;
      end if;
    else
      -- Overnight range: today's late-night portion.
      if local_time >= today_hours.open_time then
        return true;
      end if;
    end if;
  end if;

  -- Previous day's overnight range: today's after-midnight portion.
  select * into prev_hours
  from public.branch_website_hours
  where branch_id = p_branch_id
    and business_id=v_business_id
    and day_of_week = prev_dow;

  if found
     and coalesce(prev_hours.enabled, false)
     and prev_hours.open_time > prev_hours.close_time
     and local_time < prev_hours.close_time then
    return true;
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_branch_website_open(p_branch_id bigint, p_at timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_business_id uuid;
  s public.branch_website_settings%rowtype;
begin
  v_business_id:=public.mt1_require_request_business();
  perform public.mt1_require_public_branch(p_branch_id);
  select * into s
  from public.branch_website_settings
  where branch_id = p_branch_id
    and business_id=v_business_id;

  if found then
    if not coalesce(s.orders_open, true) then
      return false;
    end if;

    if s.orders_paused_until is not null
       and s.orders_paused_until > p_at then
      return false;
    end if;
  end if;

  return public.is_branch_website_schedule_open(p_branch_id, p_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_website_order(p_branch_id bigint, p_customer_name text, p_customer_phone text, p_customer_address text, p_customer_notes text, p_items jsonb, p_payment_method_code text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_payment_receipt_path text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id bigint;
  v_subtotal numeric(12,2):=0;
  v_total numeric(12,2):=0;
  v_item jsonb;
  v_product public.products%rowtype;
  v_variant public.product_variants%rowtype;
  v_qty integer;
  v_unit numeric(12,2);
  v_extras numeric(12,2);
  v_line numeric(12,2);
  v_wi bigint;
  v_modifier jsonb;
  v_mod public.modifiers%rowtype;
  v_payment public.payment_methods%rowtype;
  v_bpm public.branch_payment_methods%rowtype;
  v_bs public.branch_website_settings%rowtype;
begin
  if nullif(trim(p_customer_name),'') is null then
    raise exception 'اسم العميل مطلوب';
  end if;

  if nullif(trim(p_customer_phone),'') is null then
    raise exception 'رقم الهاتف مطلوب';
  end if;

  if nullif(trim(p_customer_address),'') is null then
    raise exception 'عنوان التوصيل مطلوب';
  end if;

  if p_items is null or jsonb_array_length(p_items)=0 then
    raise exception 'السلة فارغة';
  end if;

  if not exists(
    select 1
    from public.branches
    where id=p_branch_id
      and active=true
      and website_visible=true
  ) then
    raise exception 'الفرع غير متاح';
  end if;

  select *
  into v_bs
  from public.branch_website_settings
  where branch_id=p_branch_id;

  if found then
    if v_bs.orders_open=false then
      raise exception 'الفرع أوقف استقبال الطلبات';
    end if;

    if v_bs.orders_paused_until is not null
       and v_bs.orders_paused_until>now() then
      raise exception 'الفرع أوقف استقبال الطلبات مؤقتًا';
    end if;
  end if;

  select *
  into v_payment
  from public.payment_methods
  where code=coalesce(nullif(trim(p_payment_method_code),''),'cash')
    and active=true;

  if not found then
    raise exception 'طريقة الدفع غير متاحة';
  end if;

  select *
  into v_bpm
  from public.branch_payment_methods
  where branch_id=p_branch_id
    and payment_method_id=v_payment.id
    and active=true
    and website_enabled=true;

  if not found then
    raise exception 'طريقة الدفع غير متاحة على الموقع لهذا الفرع';
  end if;

  for v_item in
    select * from jsonb_array_elements(p_items)
  loop
    select *
    into v_product
    from public.products
    where id=(v_item->>'product_id')::bigint
      and active=true
      and website_visible=true;

    if not found then
      raise exception 'أحد الأصناف غير متاح';
    end if;

    if not exists(
      select 1
      from public.branch_products bp
      where bp.branch_id=p_branch_id
        and bp.product_id=v_product.id
        and bp.active=true
        and (
          bp.website_paused_until is null
          or bp.website_paused_until<=now()
        )
    ) then
      raise exception 'أحد الأصناف غير متاح في الفرع';
    end if;

    v_qty:=greatest(
      1,
      coalesce((v_item->>'quantity')::integer,1)
    );

    if nullif(v_item->>'variant_id','') is not null then
      select *
      into v_variant
      from public.product_variants
      where id=(v_item->>'variant_id')::bigint
        and product_id=v_product.id
        and active=true;

      if not found then
        raise exception 'اختيار الحجم غير متاح';
      end if;

      v_unit:=v_variant.price;
    else
      select coalesce(bp.price_override,v_product.price)
      into v_unit
      from public.branch_products bp
      where bp.branch_id=p_branch_id
        and bp.product_id=v_product.id;
    end if;

    v_extras:=0;

    for v_modifier in
      select *
      from jsonb_array_elements(
        coalesce(v_item->'modifiers','[]'::jsonb)
      )
    loop
      select *
      into v_mod
      from public.modifiers
      where id=(v_modifier->>'modifier_id')::bigint
        and active=true;

      if not found
         or not exists(
           select 1
           from public.product_modifiers pm
           where pm.product_id=v_product.id
             and pm.modifier_id=v_mod.id
         ) then
        raise exception 'إضافة غير متاحة';
      end if;

      v_extras:=v_extras+coalesce(v_mod.price,0);
    end loop;

    v_line:=(v_unit+v_extras)*v_qty;
    v_subtotal:=v_subtotal+v_line;
  end loop;

  v_total:=v_subtotal;

  insert into public.website_orders(
    branch_id,
    customer_name,
    customer_phone,
    customer_address,
    customer_notes,
    subtotal,
    delivery_fee,
    total,
    status,
    payment_method_code,
    payment_method_name,
    payment_reference,
    payment_receipt_path,
    payment_status
  )
  values(
    p_branch_id,
    trim(p_customer_name),
    trim(p_customer_phone),
    trim(p_customer_address),
    nullif(trim(coalesce(p_customer_notes,'')),''),
    v_subtotal,
    0,
    v_total,
    'pending',
    v_payment.code,
    v_payment.name,
    nullif(trim(coalesce(p_payment_reference,'')),''),
    nullif(trim(coalesce(p_payment_receipt_path,'')),''),
    case
      when v_payment.code='cash' then 'unpaid'
      else
        case
          when p_payment_receipt_path is not null
            or nullif(trim(coalesce(p_payment_reference,'')),'') is not null
          then 'proof_submitted'
          else 'unpaid'
        end
    end
  )
  returning id into v_order_id;

  for v_item in
    select * from jsonb_array_elements(p_items)
  loop
    select *
    into v_product
    from public.products
    where id=(v_item->>'product_id')::bigint;

    v_qty:=greatest(
      1,
      coalesce((v_item->>'quantity')::integer,1)
    );

    if nullif(v_item->>'variant_id','') is not null then
      select *
      into v_variant
      from public.product_variants
      where id=(v_item->>'variant_id')::bigint;

      v_unit:=v_variant.price;
    else
      select coalesce(bp.price_override,v_product.price)
      into v_unit
      from public.branch_products bp
      where bp.branch_id=p_branch_id
        and bp.product_id=v_product.id;

      v_variant.id:=null;
      v_variant.name:=null;
    end if;

    v_extras:=0;

    for v_modifier in
      select *
      from jsonb_array_elements(
        coalesce(v_item->'modifiers','[]'::jsonb)
      )
    loop
      select *
      into v_mod
      from public.modifiers
      where id=(v_modifier->>'modifier_id')::bigint;

      v_extras:=v_extras+coalesce(v_mod.price,0);
    end loop;

    v_line:=(v_unit+v_extras)*v_qty;

    insert into public.website_order_items(
      website_order_id,
      product_id,
      product_name,
      variant_id,
      variant_name,
      quantity,
      unit_price,
      extras_total,
      line_total,
      notes
    )
    values(
      v_order_id,
      v_product.id,
      v_product.name,
      v_variant.id,
      v_variant.name,
      v_qty,
      v_unit,
      v_extras,
      v_line,
      nullif(trim(coalesce(v_item->>'notes','')),'')
    )
    returning id into v_wi;

    for v_modifier in
      select *
      from jsonb_array_elements(
        coalesce(v_item->'modifiers','[]'::jsonb)
      )
    loop
      select *
      into v_mod
      from public.modifiers
      where id=(v_modifier->>'modifier_id')::bigint;

      insert into public.website_order_item_modifiers(
        website_order_item_id,
        modifier_id,
        modifier_name,
        price
      )
      values(
        v_wi,
        v_mod.id,
        v_mod.name,
        v_mod.price
      );
    end loop;
  end loop;

  return v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.preview_promo_code(p_code text, p_branch_id bigint, p_channel text, p_customer_phone text, p_items jsonb, p_subtotal numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_business_id uuid;
  v public.promo_codes%rowtype;
  v_phone text;
  v_used integer:=0;
  v_phone_used integer:=0;
  v_eligible numeric(12,2):=0;
  v_discount numeric(12,2):=0;
  x jsonb;
  v_product_id bigint;
  v_line numeric(12,2);
begin
  v_business_id:=public.mt1_require_request_business();
  perform public.mt1_require_public_branch(p_branch_id);
  perform public.mt1_assert_restaurant_items(p_items,v_business_id);

  select * into v
  from public.promo_codes
  where business_id=v_business_id
    and upper(trim(code))=upper(trim(coalesce(p_code,'')))
  limit 1;

  if not found or v.active=false then raise exception 'البرومو كود غير صحيح أو غير فعال'; end if;
  if v.starts_at is not null and now()<v.starts_at then raise exception 'البرومو كود لم يبدأ بعد'; end if;
  if v.ends_at is not null and now()>v.ends_at then raise exception 'انتهت صلاحية البرومو كود'; end if;
  if v.channel<>'both' and v.channel<>p_channel then raise exception 'البرومو كود غير متاح على هذه القناة'; end if;
  if coalesce(p_subtotal,0)<coalesce(v.min_order,0) then raise exception 'الحد الأدنى للطلب هو %',v.min_order; end if;

  if exists(select 1 from public.promo_code_branches where business_id=v_business_id and promo_code_id=v.id)
     and not exists(select 1 from public.promo_code_branches where business_id=v_business_id and promo_code_id=v.id and branch_id=p_branch_id) then
    raise exception 'البرومو كود غير متاح لهذا الفرع';
  end if;

  select count(*) into v_used from public.promo_redemptions where business_id=v_business_id and promo_code_id=v.id;
  if v.max_uses is not null and v.max_uses>0 and v_used>=v.max_uses then raise exception 'تم استنفاد عدد استخدامات البرومو كود'; end if;

  v_phone:=regexp_replace(coalesce(p_customer_phone,''),'\D','','g');
  if coalesce(v.max_uses_per_phone,0)>0 then
    if length(v_phone)<8 then raise exception 'رقم الموبايل مطلوب لاستخدام البرومو كود'; end if;
    select count(*) into v_phone_used from public.promo_redemptions
    where business_id=v_business_id and promo_code_id=v.id and regexp_replace(coalesce(customer_phone,''),'\D','','g')=v_phone;
    if v_phone_used>=v.max_uses_per_phone then raise exception 'تم استخدام البرومو كود بالحد الأقصى لهذا الرقم'; end if;
  end if;

  if v.scope='all' then
    v_eligible:=coalesce(p_subtotal,0);
  else
    for x in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
      v_product_id:=nullif(x->>'product_id','')::bigint;
      v_line:=coalesce((x->>'line_total')::numeric,0);
      if v.scope='products' and exists(select 1 from public.promo_code_products pp where pp.business_id=v_business_id and pp.promo_code_id=v.id and pp.product_id=v_product_id) then
        v_eligible:=v_eligible+v_line;
      elsif v.scope='categories' and exists(
        select 1 from public.products p join public.promo_code_categories pc on pc.category_id=p.category_id and pc.business_id=v_business_id
        where p.business_id=v_business_id and p.id=v_product_id and pc.promo_code_id=v.id
      ) then
        v_eligible:=v_eligible+v_line;
      end if;
    end loop;
  end if;

  if v_eligible<=0 then raise exception 'البرومو كود لا ينطبق على الأصناف الموجودة في الطلب'; end if;
  if v.discount_type='percent' then v_discount:=round(v_eligible*v.discount_value/100,2);
  else v_discount:=least(v.discount_value,v_eligible); end if;
  if v.max_discount is not null and v.max_discount>0 then v_discount:=least(v_discount,v.max_discount); end if;
  v_discount:=greatest(0,least(v_discount,coalesce(p_subtotal,0)));

  return jsonb_build_object(
    'valid',true,'promo_id',v.id,'code',v.code,'name',coalesce(v.name,v.code),
    'discount',v_discount,'eligible_subtotal',v_eligible,'discount_type',v.discount_type,'discount_value',v.discount_value
  );
end;
$function$

CREATE OR REPLACE FUNCTION sharawla_internal.top_chicken_normalize_mobile(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v text;
BEGIN
 v := translate(btrim(coalesce(p_phone,'')), '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789');
 IF v = '' OR v ~ '[^0-9+() .[:space:]-]' THEN RETURN NULL; END IF;
 v := regexp_replace(v, '[^0-9]', '', 'g');
 IF left(v,4)='0020' AND length(v)=14 THEN v:='0'||substr(v,5);
 ELSIF left(v,2)='20' AND length(v)=12 THEN v:='0'||substr(v,3);
 ELSIF length(v)=10 AND left(v,1)='1' THEN v:='0'||v; END IF;
 IF v !~ '^01[0125][0-9]{8}$' THEN RETURN NULL; END IF;
 RETURN v;
END $function$

CREATE OR REPLACE FUNCTION sharawla_internal.top_chicken_resolve_website_customer(p_website_order_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
 v_business constant uuid := '5358328c-9724-49aa-affc-1bce8be90f92';
 w public.website_orders%rowtype; v_phone text; v_customer_id bigint; v_count bigint;
 v_address text; v_area text;
BEGIN
 IF auth.uid() IS NULL OR public.current_business_id() IS DISTINCT FROM v_business
 OR public.current_employee_id() IS NULL OR NOT public.has_branch_access(22)
 THEN RAISE EXCEPTION 'TOP_CHICKEN_CUSTOMER_SCOPE_DENIED'; END IF;
 SELECT * INTO w FROM public.website_orders
 WHERE id=p_website_order_id AND business_id=v_business AND branch_id=22;
 IF NOT FOUND OR w.status <> 'pending' THEN RAISE EXCEPTION 'TOP_CHICKEN_WEBSITE_ORDER_INVALID'; END IF;
 v_phone:=sharawla_internal.top_chicken_normalize_mobile(w.customer_phone);
 IF v_phone IS NULL THEN RAISE EXCEPTION 'TOP_CHICKEN_CUSTOMER_PHONE_INVALID'; END IF;
 -- Serialize customer/address resolution for concurrent orders with the same mobile.
 PERFORM pg_advisory_xact_lock(hashtextextended(v_business::text||':'||v_phone,0));
 SELECT count(*),min(c.id) INTO v_count,v_customer_id FROM public.customers c
 WHERE c.business_id=v_business AND sharawla_internal.top_chicken_normalize_mobile(c.phone)=v_phone;
 IF v_count>1 THEN RAISE EXCEPTION 'TOP_CHICKEN_CUSTOMER_PHONE_AMBIGUOUS'; END IF;
 IF coalesce(w.order_type,'delivery')='delivery' THEN
  v_address:=nullif(btrim(w.customer_address),'');
  IF v_address IS NULL THEN RAISE EXCEPTION 'TOP_CHICKEN_CUSTOMER_ADDRESS_REQUIRED'; END IF;
  SELECT name INTO v_area FROM public.delivery_zones
  WHERE id=w.delivery_zone_id AND business_id=v_business AND branch_id=22;
  IF NOT FOUND THEN RAISE EXCEPTION 'TOP_CHICKEN_DELIVERY_ZONE_INVALID'; END IF;
 END IF;
 IF v_customer_id IS NULL THEN
  INSERT INTO public.customers(business_id,name,phone,address,area)
  VALUES(v_business,btrim(w.customer_name),v_phone,v_address,v_area) RETURNING id INTO v_customer_id;
 END IF;
 -- Existing customer profile and all imported fields are preserved.
 IF v_address IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM public.customer_addresses a WHERE a.business_id=v_business AND a.customer_id=v_customer_id
  AND sharawla_internal.top_chicken_normalize_address_text(a.address)=sharawla_internal.top_chicken_normalize_address_text(v_address)
  AND sharawla_internal.top_chicken_normalize_address_text(a.area)=sharawla_internal.top_chicken_normalize_address_text(v_area)
 ) THEN
  INSERT INTO public.customer_addresses(business_id,customer_id,label,address,area,is_default)
  VALUES(v_business,v_customer_id,'عنوان الموقع',v_address,v_area,
   NOT EXISTS(SELECT 1 FROM public.customer_addresses a WHERE a.business_id=v_business AND a.customer_id=v_customer_id AND a.is_default));
 END IF;
 RETURN v_customer_id;
END $function$

CREATE OR REPLACE FUNCTION public.top_chicken_create_website_order(p_request_id uuid, p_branch_id bigint, p_customer_name text, p_customer_phone text, p_customer_address text, p_customer_notes text, p_items jsonb, p_payment_method_code text, p_payment_reference text, p_payment_receipt_path text, p_order_type text, p_promo_code text, p_delivery_zone_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_business_id uuid;
  v_phone text;
  v_fingerprint text;
  v_receipt sharawla_internal.top_chicken_website_request_receipts%ROWTYPE;
  v_order_id bigint;
BEGIN
  v_business_id:=public.mt1_require_request_business();
  IF v_business_id IS DISTINCT FROM '5358328c-9724-49aa-affc-1bce8be90f92'::uuid
     OR p_branch_id IS DISTINCT FROM 22::bigint
  THEN RAISE EXCEPTION 'TOP_CHICKEN_REQUEST_SCOPE_DENIED' USING errcode='42501'; END IF;
  PERFORM public.mt1_require_public_branch(p_branch_id);
  IF p_request_id IS NULL OR p_request_id='00000000-0000-0000-0000-000000000000'::uuid
  THEN RAISE EXCEPTION 'TOP_CHICKEN_REQUEST_ID_REQUIRED'; END IF;
  v_phone:=sharawla_internal.top_chicken_normalize_mobile(p_customer_phone);
  IF v_phone IS NULL THEN RAISE EXCEPTION 'TOP_CHICKEN_CUSTOMER_PHONE_INVALID'; END IF;
  v_fingerprint:=encode(sha256(convert_to(jsonb_build_object(
    'branch',p_branch_id,'name',p_customer_name,'phone',v_phone,
    'address',p_customer_address,'notes',p_customer_notes,'items',p_items,
    'payment',p_payment_method_code,'reference',p_payment_reference,
    'receipt',p_payment_receipt_path,'type',p_order_type,
    'promo',p_promo_code,'zone',p_delivery_zone_id
  )::text,'UTF8')),'hex');
  -- Serializes the same request; the receipt and order commit atomically.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    v_business_id::text||':22:website-request:'||p_request_id::text,0));
  SELECT * INTO v_receipt
  FROM sharawla_internal.top_chicken_website_request_receipts
  WHERE business_id=v_business_id AND branch_id=p_branch_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt.request_fingerprint IS DISTINCT FROM v_fingerprint
    THEN RAISE EXCEPTION 'TOP_CHICKEN_REQUEST_ID_CONFLICT'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.website_orders
      WHERE id=v_receipt.website_order_id AND business_id=v_business_id AND branch_id=22)
    THEN RAISE EXCEPTION 'TOP_CHICKEN_REQUEST_RECEIPT_INVALID'; END IF;
    RETURN v_receipt.website_order_id;
  END IF;
  -- Delegate all current catalog, price, zone, payment and closed-gate checks.
  v_order_id:=public.create_website_order(p_branch_id,p_customer_name,v_phone,
    p_customer_address,p_customer_notes,p_items,p_payment_method_code,
    p_payment_reference,p_payment_receipt_path,p_order_type,p_promo_code,p_delivery_zone_id);
  INSERT INTO sharawla_internal.top_chicken_website_request_receipts
    (business_id,branch_id,request_id,request_fingerprint,website_order_id)
  VALUES (v_business_id,p_branch_id,p_request_id,v_fingerprint,v_order_id);
  RETURN v_order_id;
END $function$

CREATE OR REPLACE FUNCTION public.create_website_order(p_branch_id bigint, p_customer_name text, p_customer_phone text, p_customer_address text, p_customer_notes text, p_items jsonb, p_payment_method_code text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_payment_receipt_path text DEFAULT NULL::text, p_order_type text DEFAULT 'delivery'::text, p_promo_code text DEFAULT NULL::text, p_delivery_zone_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_business_id uuid;
  v_order_id bigint;
  v_subtotal numeric(12,2):=0;
  v_total numeric(12,2):=0;
  v_delivery_fee numeric(12,2):=0;
  v_item jsonb;
  v_product public.products%rowtype;
  v_variant public.product_variants%rowtype;
  v_zone public.delivery_zones%rowtype;
  v_qty integer;
  v_unit numeric(12,2);
  v_extras numeric(12,2);
  v_line numeric(12,2);
  v_wi bigint;
  v_modifier jsonb;
  v_mod public.modifiers%rowtype;
  v_payment public.payment_methods%rowtype;
  v_bpm public.branch_payment_methods%rowtype;
  v_bs public.branch_website_settings%rowtype;
  v_type text;
  v_calc_items jsonb:='[]'::jsonb;
  v_promo jsonb;
  v_promo_id bigint;
  v_promo_discount numeric(12,2):=0;
begin
  v_business_id:=public.mt1_require_request_business();
  perform public.mt1_require_public_branch(p_branch_id);
  perform public.mt1_assert_restaurant_items(p_items,v_business_id);

  -- Only Top Chicken Beta uses canonical mobile identity; other activities are unchanged.
  if v_business_id='5358328c-9724-49aa-affc-1bce8be90f92'::uuid then
    if p_branch_id<>22 then
      raise exception 'TOP_CHICKEN_CUSTOMER_SCOPE_DENIED';
    end if;
    p_customer_phone:=sharawla_internal.top_chicken_normalize_mobile(p_customer_phone);
    if p_customer_phone is null then
      raise exception 'TOP_CHICKEN_CUSTOMER_PHONE_INVALID';
    end if;
  end if;

  if nullif(trim(coalesce(p_payment_receipt_path,'')),'') is not null
     and split_part(trim(p_payment_receipt_path),'/',1) is distinct from v_business_id::text then
    raise exception 'PAYMENT_RECEIPT_TENANT_MISMATCH' using errcode='42501';
  end if;

  v_type:=lower(coalesce(nullif(trim(p_order_type),''),'delivery'));

  if v_type not in ('delivery','pickup') then
    raise exception 'نوع الاستلام غير صحيح';
  end if;

  if nullif(trim(p_customer_name),'') is null then
    raise exception 'اسم العميل مطلوب';
  end if;

  if nullif(trim(p_customer_phone),'') is null then
    raise exception 'رقم الهاتف مطلوب';
  end if;

  if v_type='delivery'
     and nullif(trim(coalesce(p_customer_address,'')),'') is null then
    raise exception 'عنوان التوصيل مطلوب';
  end if;

  if p_items is null or jsonb_array_length(p_items)=0 then
    raise exception 'السلة فارغة';
  end if;

  if not exists(
    select 1
    from public.branches
    where id=p_branch_id
      and business_id=v_business_id
      and active=true
      and website_visible=true
  ) then
    raise exception 'الفرع غير متاح';
  end if;

  select *
  into v_bs
  from public.branch_website_settings
  where branch_id=p_branch_id
    and business_id=v_business_id;

  if found and (
    v_bs.orders_open=false
    or (
      v_bs.orders_paused_until is not null
      and v_bs.orders_paused_until>now()
    )
  ) then
    raise exception 'الفرع أوقف استقبال الطلبات';
  end if;

  if v_type='delivery' then
    if p_delivery_zone_id is null then
      raise exception 'اختار منطقة التوصيل';
    end if;

    select *
    into v_zone
    from public.delivery_zones
    where id=p_delivery_zone_id
      and branch_id=p_branch_id
      and business_id=v_business_id
      and active=true;

    if not found then
      raise exception 'منطقة التوصيل غير متاحة لهذا الفرع';
    end if;

    v_delivery_fee:=greatest(0,coalesce(v_zone.delivery_fee,0));
  else
    p_delivery_zone_id:=null;
    v_delivery_fee:=0;
  end if;

  select *
  into v_payment
  from public.payment_methods
  where business_id=v_business_id
    and code=coalesce(nullif(trim(p_payment_method_code),''),'cash')
    and active=true;

  if not found then
    raise exception 'طريقة الدفع غير متاحة';
  end if;

  select *
  into v_bpm
  from public.branch_payment_methods
  where business_id=v_business_id
    and branch_id=p_branch_id
    and payment_method_id=v_payment.id
    and active=true
    and website_enabled=true;

  if not found then
    raise exception 'طريقة الدفع غير متاحة على الموقع لهذا الفرع';
  end if;

  for v_item in
    select * from jsonb_array_elements(p_items)
  loop

    select *
    into v_product
    from public.products
    where business_id=v_business_id
      and id=(v_item->>'product_id')::bigint
      and active=true
      and website_visible=true;

    if not found then
      raise exception 'أحد الأصناف غير متاح';
    end if;

    if not exists(
      select 1
      from public.branch_products bp
      where bp.business_id=v_business_id
        and bp.branch_id=p_branch_id
        and bp.product_id=v_product.id
        and bp.active=true
        and (
          bp.website_paused_until is null
          or bp.website_paused_until<=now()
        )
    ) then
      raise exception 'أحد الأصناف غير متاح في الفرع';
    end if;

    v_qty:=greatest(1,coalesce((v_item->>'quantity')::integer,1));

    if nullif(v_item->>'variant_id','') is not null then

      select *
      into v_variant
      from public.product_variants
      where business_id=v_business_id
        and id=(v_item->>'variant_id')::bigint
        and product_id=v_product.id
        and active=true;

      if not found then
        raise exception 'اختيار الحجم غير متاح';
      end if;

      v_unit:=v_variant.price;

    else

      select coalesce(bp.price_override,v_product.price)
      into v_unit
      from public.branch_products bp
      where bp.business_id=v_business_id
        and bp.branch_id=p_branch_id
        and bp.product_id=v_product.id;

    end if;

    v_extras:=0;

    for v_modifier in
      select *
      from jsonb_array_elements(
        coalesce(v_item->'modifiers','[]'::jsonb)
      )
    loop

      select *
      into v_mod
      from public.modifiers
      where business_id=v_business_id
        and id=(v_modifier->>'modifier_id')::bigint
        and active=true;

      if not found
         or not exists(
           select 1
           from public.product_modifiers pm
           where pm.business_id=v_business_id
             and pm.product_id=v_product.id
             and pm.modifier_id=v_mod.id
         )
      then
        raise exception 'إضافة غير متاحة';
      end if;

      v_extras:=v_extras+coalesce(v_mod.price,0);

    end loop;

    v_line:=(v_unit+v_extras)*v_qty;
    v_subtotal:=v_subtotal+v_line;

    v_calc_items:=v_calc_items||
      jsonb_build_array(
        jsonb_build_object(
          'product_id',v_product.id,
          'line_total',v_line
        )
      );

  end loop;

  if nullif(trim(coalesce(p_promo_code,'')),'') is not null then

    v_promo:=public.preview_promo_code(
      p_promo_code,
      p_branch_id,
      'website',
      p_customer_phone,
      v_calc_items,
      v_subtotal
    );

    v_promo_id:=(v_promo->>'promo_id')::bigint;
    v_promo_discount:=coalesce((v_promo->>'discount')::numeric,0);

  end if;

  v_total:=greatest(
    0,
    v_subtotal-v_promo_discount+v_delivery_fee
  );

  insert into public.website_orders(
    branch_id,
    customer_name,
    customer_phone,
    customer_address,
    customer_notes,
    subtotal,
    delivery_fee,
    delivery_zone_id,
    total,
    status,
    payment_method_code,
    payment_method_name,
    payment_reference,
    payment_receipt_path,
    payment_status,
    order_type,
    promo_code_id,
    promo_code,
    promo_discount
  )
  values(
    p_branch_id,
    trim(p_customer_name),
    trim(p_customer_phone),

    case
      when v_type='pickup' then null
      else trim(p_customer_address)
    end,

    nullif(trim(coalesce(p_customer_notes,'')),''),

    v_subtotal,
    v_delivery_fee,
    p_delivery_zone_id,
    v_total,
    'pending',

    v_payment.code,
    v_payment.name,

    nullif(trim(coalesce(p_payment_reference,'')),''),

    nullif(
      trim(coalesce(p_payment_receipt_path,'')),
      ''
    ),

    case
      when v_payment.code='cash'
        then 'unpaid'
      else
        case
          when p_payment_receipt_path is not null
            or nullif(
              trim(coalesce(p_payment_reference,'')),
              ''
            ) is not null
          then 'proof_submitted'
          else 'unpaid'
        end
    end,

    v_type,
    v_promo_id,

    case
      when v_promo_id is null
        then null
      else upper(trim(p_promo_code))
    end,

    v_promo_discount

  )
  returning id into v_order_id;

  for v_item in
    select * from jsonb_array_elements(p_items)
  loop

    select *
    into v_product
    from public.products
    where business_id=v_business_id
      and id=(v_item->>'product_id')::bigint;

    v_qty:=greatest(
      1,
      coalesce((v_item->>'quantity')::integer,1)
    );

    if nullif(v_item->>'variant_id','') is not null then

      select *
      into v_variant
      from public.product_variants
      where business_id=v_business_id
        and id=(v_item->>'variant_id')::bigint;

      v_unit:=v_variant.price;

    else

      select coalesce(bp.price_override,v_product.price)
      into v_unit
      from public.branch_products bp
      where bp.business_id=v_business_id
        and bp.branch_id=p_branch_id
        and bp.product_id=v_product.id;

      v_variant.id:=null;
      v_variant.name:=null;

    end if;

    v_extras:=0;

    for v_modifier in
      select *
      from jsonb_array_elements(
        coalesce(v_item->'modifiers','[]'::jsonb)
      )
    loop

      select *
      into v_mod
      from public.modifiers
      where business_id=v_business_id
        and id=(v_modifier->>'modifier_id')::bigint;

      v_extras:=v_extras+coalesce(v_mod.price,0);

    end loop;

    v_line:=(v_unit+v_extras)*v_qty;

    insert into public.website_order_items(
      website_order_id,
      product_id,
      product_name,
      variant_id,
      variant_name,
      quantity,
      unit_price,
      extras_total,
      line_total,
      notes
    )
    values(
      v_order_id,
      v_product.id,
      v_product.name,
      v_variant.id,
      v_variant.name,
      v_qty,
      v_unit,
      v_extras,
      v_line,
      nullif(
        trim(coalesce(v_item->>'notes','')),
        ''
      )
    )
    returning id into v_wi;

    for v_modifier in
      select *
      from jsonb_array_elements(
        coalesce(v_item->'modifiers','[]'::jsonb)
      )
    loop

      select *
      into v_mod
      from public.modifiers
      where business_id=v_business_id
        and id=(v_modifier->>'modifier_id')::bigint;

      insert into public.website_order_item_modifiers(
        website_order_item_id,
        modifier_id,
        modifier_name,
        price
      )
      values(
        v_wi,
        v_mod.id,
        v_mod.name,
        v_mod.price
      );

    end loop;

  end loop;

  if v_promo_id is not null then

    perform public.redeem_promo_code(
      v_promo_id,
      upper(trim(p_promo_code)),
      p_branch_id,
      'website',
      p_customer_phone,
      v_promo_discount,
      null,
      v_order_id
    );

  end if;

  return v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_order_payment(p_order_id bigint, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders%rowtype;
declare v_emp bigint;
begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;
  if not public.has_action_permission_v2('orders.payment.review') then
    raise exception 'ORDER_PAYMENT_REVIEW_DENIED';
  end if;
  if p_status not in ('unpaid','proof_submitted','confirmed','rejected') then raise exception 'حالة دفع غير صحيحة'; end if;
  v_emp:=public.current_employee_id();
  select * into o from public.orders where id=p_order_id for update;
  if not found then raise exception 'الطلب غير موجود'; end if;
  if not public.has_branch_access(o.branch_id) then raise exception 'ليس لديك صلاحية لهذا الفرع'; end if;
  update public.orders set payment_status=p_status where id=o.id;
  if o.website_order_id is not null then
    update public.website_orders set payment_status=p_status,payment_reviewed_at=now(),payment_reviewed_by=v_emp where id=o.website_order_id;
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_promo_code(p_promo_id bigint, p_code text, p_branch_id bigint, p_channel text, p_customer_phone text, p_discount numeric, p_order_id bigint DEFAULT NULL::bigint, p_website_order_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if p_channel='pos' and auth.uid() is null then raise exception 'غير مصرح'; end if;
  insert into public.promo_redemptions(promo_code_id,code,branch_id,channel,customer_phone,discount_amount,order_id,website_order_id)
  values(p_promo_id,p_code,p_branch_id,p_channel,nullif(trim(coalesce(p_customer_phone,'')),''),greatest(0,coalesce(p_discount,0)),p_order_id,p_website_order_id)
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.mt1_require_request_business()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v uuid;
begin
  v:=public.request_business_id();
  if v is null then
    raise exception 'MULTITENANT_CONTEXT_REQUIRED' using errcode='42501';
  end if;
  return v;
end
$function$

CREATE OR REPLACE FUNCTION public.mt1_require_public_branch(p_branch_id bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v uuid;
begin
  v:=public.mt1_require_request_business();
  if not exists(
    select 1 from public.branches b
    where b.id=p_branch_id
      and b.business_id=v
      and b.active is distinct from false
      and b.website_visible=true
  ) then
    raise exception 'BRANCH_NOT_AVAILABLE' using errcode='42501';
  end if;
  return v;
end
$function$

CREATE OR REPLACE FUNCTION public.mt1_assert_restaurant_items(p_items jsonb, p_business_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare x jsonb; m jsonb; pid bigint; vid bigint; mid bigint;
begin
  if p_business_id is null then
    raise exception 'MULTITENANT_CONTEXT_REQUIRED' using errcode='42501';
  end if;
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb))
  loop
    pid:=nullif(x->>'product_id','')::bigint;
    if pid is null or not exists(
      select 1 from public.products p where p.id=pid and p.business_id=p_business_id
    ) then
      raise exception 'ITEM_NOT_AVAILABLE';
    end if;

    vid:=nullif(x->>'variant_id','')::bigint;
    if vid is not null and not exists(
      select 1 from public.product_variants v
      where v.id=vid and v.product_id=pid and v.business_id=p_business_id
    ) then
      raise exception 'ITEM_NOT_AVAILABLE';
    end if;

    if jsonb_typeof(x->'modifiers')='array' then
      for m in select value from jsonb_array_elements(x->'modifiers')
      loop
        mid:=nullif(m->>'modifier_id','')::bigint;
        if mid is null or not exists(
          select 1
          from public.modifiers mm
          join public.product_modifiers pm
            on pm.modifier_id=mm.id
           and pm.product_id=pid
           and pm.business_id=p_business_id
          where mm.id=mid and mm.business_id=p_business_id
        ) then
          raise exception 'ITEM_NOT_AVAILABLE';
        end if;
      end loop;
    end if;
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION public.create_website_order(p_branch_id bigint, p_customer_name text, p_customer_phone text, p_customer_address text, p_customer_notes text, p_items jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id bigint;
  v_item jsonb;
  v_modifier jsonb;

  v_product_id bigint;
  v_variant_id bigint;
  v_qty integer;

  v_product_name text;
  v_variant_name text;

  v_unit_price numeric(12,2);
  v_extra_price numeric(12,2);
  v_extras_total numeric(12,2);
  v_line_total numeric(12,2);
  v_subtotal numeric(12,2) := 0;

  v_item_id bigint;
  v_modifier_id bigint;
  v_modifier_name text;
begin

  if p_customer_name is null or btrim(p_customer_name) = '' then
    raise exception 'customer_name_required';
  end if;

  if p_customer_phone is null or btrim(p_customer_phone) = '' then
    raise exception 'customer_phone_required';
  end if;

  if p_customer_address is null or btrim(p_customer_address) = '' then
    raise exception 'customer_address_required';
  end if;

  if not exists (
    select 1 from public.branches
    where id = p_branch_id
  ) then
    raise exception 'invalid_branch';
  end if;

  if p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 then
    raise exception 'empty_order';
  end if;

  insert into public.website_orders (
    branch_id,
    customer_name,
    customer_phone,
    customer_address,
    customer_notes,
    status
  )
  values (
    p_branch_id,
    btrim(p_customer_name),
    btrim(p_customer_phone),
    btrim(p_customer_address),
    nullif(btrim(coalesce(p_customer_notes,'')), ''),
    'new'
  )
  returning id into v_order_id;

  for v_item in
    select value from jsonb_array_elements(p_items)
  loop

    v_product_id := nullif(v_item->>'product_id','')::bigint;
    v_variant_id := nullif(v_item->>'variant_id','')::bigint;

    v_qty := greatest(
      coalesce(nullif(v_item->>'quantity','')::integer, 1),
      1
    );

    v_product_name := null;
    v_unit_price := null;

    select p.name, coalesce(bp.price_override, p.price)
    into v_product_name, v_unit_price
    from public.products p
    join public.branch_products bp
      on bp.product_id = p.id
     and bp.branch_id = p_branch_id
    where p.id = v_product_id
      and p.active = true
      and p.website_visible = true
      and bp.active = true
    limit 1;

    if v_product_name is null then
      raise exception 'invalid_product';
    end if;

    v_variant_name := null;

    if v_variant_id is not null then

      select pv.name, pv.price
      into v_variant_name, v_unit_price
      from public.product_variants pv
      where pv.id = v_variant_id
        and pv.product_id = v_product_id
        and pv.active = true
      limit 1;

      if v_variant_name is null then
        raise exception 'invalid_variant';
      end if;

    end if;

    v_extras_total := 0;

    insert into public.website_order_items (
      website_order_id,
      product_id,
      product_name,
      variant_id,
      variant_name,
      quantity,
      unit_price,
      extras_total,
      line_total,
      notes
    )
    values (
      v_order_id,
      v_product_id,
      v_product_name,
      v_variant_id,
      v_variant_name,
      v_qty,
      v_unit_price,
      0,
      0,
      nullif(btrim(coalesce(v_item->>'notes','')), '')
    )
    returning id into v_item_id;

    if jsonb_typeof(v_item->'modifiers') = 'array' then

      for v_modifier in
        select value
        from jsonb_array_elements(v_item->'modifiers')
      loop

        v_modifier_id :=
          nullif(v_modifier->>'modifier_id','')::bigint;

        v_modifier_name := null;
        v_extra_price := null;

        select m.name, m.price
        into v_modifier_name, v_extra_price
        from public.modifiers m
        join public.product_modifiers pm
          on pm.modifier_id = m.id
        where m.id = v_modifier_id
          and pm.product_id = v_product_id
          and m.active = true
        limit 1;

        if v_modifier_name is not null then

          insert into public.website_order_item_modifiers (
            website_order_item_id,
            modifier_id,
            modifier_name,
            price
          )
          values (
            v_item_id,
            v_modifier_id,
            v_modifier_name,
            v_extra_price
          );

          v_extras_total :=
            v_extras_total + v_extra_price;

        end if;

      end loop;

    end if;

    v_line_total :=
      (v_unit_price + v_extras_total) * v_qty;

    update public.website_order_items
    set
      extras_total = v_extras_total,
      line_total = v_line_total
    where id = v_item_id;

    v_subtotal := v_subtotal + v_line_total;

  end loop;

  update public.website_orders
  set
    subtotal = v_subtotal,
    total = v_subtotal
  where id = v_order_id;

  return v_order_id;
end;
$function$
